('d7295f18-1b24-5859-b3f7-3d24943f0e32', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d7295f18-1b24-5859-b3f7-3d24943f0e32", "kind": "sequence", "subject": "Physique-Chimie", "level": "1re", "theme": "4", "name": "La lumière : modèles ondulatoire et particulaire", "order": 12, "code": "143", "description": "Ondes électromagnétiques et domaines spectraux, photon, niveaux d''énergie. Attention aux conversions en joules et électronvolts."}'::jsonb),
('d7055b59-ed91-5de7-8e73-c9fc4a4bc50a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d7055b59-ed91-5de7-8e73-c9fc4a4bc50a", "kind": "seance", "parentId": "d7295f18-1b24-5859-b3f7-3d24943f0e32", "subject": "Physique-Chimie", "level": "1re", "theme": "4", "name": "Ondes électromagnétiques", "order": 1, "code": "1431", "description": "Échelle des fréquences et longueurs d''onde, ordres de grandeur des applications, relation $\\lambda = c/\\nu$."}'::jsonb),
('4991e38e-07ab-5296-9436-e88970f9240f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4991e38e-07ab-5296-9436-e88970f9240f", "kind": "seance", "parentId": "d7295f18-1b24-5859-b3f7-3d24943f0e32", "subject": "Physique-Chimie", "level": "1re", "theme": "4", "name": "Photon et niveaux d''énergie", "order": 2, "code": "1432", "description": "Énergie d''un photon, joule et électronvolt, diagramme de niveaux d''énergie, absorption et émission, spectres de raies."}'::jsonb);
insert into public.cards (id, owner_id, data) values
('1616349d-fa50-5612-83d3-f04fc1700c9b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1616349d-fa50-5612-83d3-f04fc1700c9b", "code": "11ER-001", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "masse molaire"], "front": "**Masse molaire** $M$ : définition et unité ?", "back": "Masse d''une mole d''entités, en $\\mathrm{g \\cdot mol^{-1}}$.\n$M = N_A \\times m_{\\text{entité}}$ avec $N_A = 6{,}02 \\times 10^{23}\\ \\mathrm{mol^{-1}}$.", "createdAt": 1793546802131, "updatedAt": 1793546802131, "ocrDone": true}'::jsonb),
('75e413c4-73d8-5692-a8cc-98095e77e6be', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "75e413c4-73d8-5692-a8cc-98095e77e6be", "code": "11ER-002", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "masse molaire", "méthode"], "front": "Comment calculer la masse molaire d''une molécule, par exemple $\\mathrm{H_2O}$ ?", "back": "On additionne les masses molaires atomiques de tous ses atomes (tableau périodique).\n$M(\\mathrm{H_2O}) = 2 \\times 1{,}0 + 16{,}0 = 18{,}0\\ \\mathrm{g \\cdot mol^{-1}}$", "createdAt": 1793546802132, "updatedAt": 1793546802132, "ocrDone": true}'::jsonb),
('bbd69ee3-2063-58de-b13a-16e34aea81d3', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "bbd69ee3-2063-58de-b13a-16e34aea81d3", "code": "11ER-003", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "quantité de matière"], "front": "Relation entre **quantité de matière**, masse et masse molaire ?", "back": "$n = \\dfrac{m}{M}$\n$n$ en mol, $m$ en g, $M$ en $\\mathrm{g \\cdot mol^{-1}}$.", "createdAt": 1793546802133, "updatedAt": 1793546802133, "ocrDone": true}'::jsonb),
('8c9d5c6b-6f73-53f6-a44e-90054c7286f4', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8c9d5c6b-6f73-53f6-a44e-90054c7286f4", "code": "11ER-004", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "volume molaire", "gaz"], "front": "**Volume molaire** d''un gaz : définition et relation ?", "back": "Volume occupé par une mole de gaz, à température et pression données.\n$n = \\dfrac{V}{V_m}$ (environ $24\\ \\mathrm{L \\cdot mol^{-1}}$ à 20 °C et 1 bar)", "createdAt": 1793546802134, "updatedAt": 1793546802134, "ocrDone": true}'::jsonb),
('a6f1dd35-860c-5e82-8cda-af5d22cecd6f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a6f1dd35-860c-5e82-8cda-af5d22cecd6f", "code": "11ER-005", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "quantité de matière", "masse volumique", "méthode"], "front": "Quantité de matière d''un **liquide pur** dont on connaît le volume ?", "back": "On passe par la masse volumique : $m = \\rho \\times V$, puis $n = \\dfrac{m}{M} = \\dfrac{\\rho V}{M}$.", "createdAt": 1793546802135, "updatedAt": 1793546802135, "ocrDone": true}'::jsonb),
('18006986-2a64-5ee8-af5c-fb134ceb36e3', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "18006986-2a64-5ee8-af5c-fb134ceb36e3", "code": "11ER-006", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "concentration"], "front": "**Concentration en quantité de matière** : définition et unité ?", "back": "$C = \\dfrac{n}{V_{\\text{solution}}}$ en $\\mathrm{mol \\cdot L^{-1}}$\nQuantité de soluté par litre de solution.", "createdAt": 1793546802136, "updatedAt": 1793546802136, "ocrDone": true}'::jsonb),
('f438417a-fcc6-5b13-b197-ccc69efb577b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f438417a-fcc6-5b13-b197-ccc69efb577b", "code": "11ER-007", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "concentration", "concentration en masse"], "front": "Lien entre concentration en masse $C_m$ et concentration en quantité de matière $C$ ?", "back": "$C_m = C \\times M$\n$C_m$ en $\\mathrm{g \\cdot L^{-1}}$, $C$ en $\\mathrm{mol \\cdot L^{-1}}$, $M$ en $\\mathrm{g \\cdot mol^{-1}}$.", "createdAt": 1793546802137, "updatedAt": 1793546802137, "ocrDone": true}'::jsonb),
('5402f78d-3978-5339-b01c-3decae4b742c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5402f78d-3978-5339-b01c-3decae4b742c", "code": "11ER-008", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "concentration", "piège"], "front": "Différence entre $n$ et $C$ : à quoi faut-il faire attention dans les calculs ?", "back": "$n$ est une **quantité** (mol) ; $C$ est une quantité **par litre** ($\\mathrm{mol \\cdot L^{-1}}$).\nPour passer de l''un à l''autre : $n = C \\times V$, avec $V$ **en litres**.", "createdAt": 1793546802138, "updatedAt": 1793546802138, "ocrDone": true}'::jsonb),
('2c4b6891-6264-5e6d-92fa-aa278b5b4680', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2c4b6891-6264-5e6d-92fa-aa278b5b4680", "code": "11ER-009", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "absorbance", "spectre"], "front": "Qu''est-ce qu''un **spectre d''absorption** UV-visible ?", "back": "Le graphique de l''absorbance $A$ en fonction de la longueur d''onde $\\lambda$.\nIl indique quelles radiations l''espèce absorbe ; on repère le maximum $\\lambda_{\\max}$.", "createdAt": 1793546802139, "updatedAt": 1793546802139, "ocrDone": true}'::jsonb),
('9a32fb60-fe41-566a-8f29-686b62c23520', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9a32fb60-fe41-566a-8f29-686b62c23520", "code": "11ER-010", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "absorbance", "couleur"], "front": "Comment prévoir la **couleur d''une solution** à partir de son spectre ?", "back": "La solution a la couleur **complémentaire** de celle qu''elle absorbe le plus.\nEx. : elle absorbe le rouge, elle paraît cyan.\nSi elle n''absorbe que dans l''UV, elle est incolore.", "createdAt": 1793546802140, "updatedAt": 1793546802140, "ocrDone": true}'::jsonb),
('d85739af-52df-54b6-9f8b-cfd135609c16', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d85739af-52df-54b6-9f8b-cfd135609c16", "code": "11ER-011", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Beer-Lambert"], "front": "Énoncer la **loi de Beer-Lambert**.", "back": "$A = k \\times C$\nL''absorbance $A$ (sans unité) est **proportionnelle** à la concentration de l''espèce colorée.\n$k$ dépend de l''espèce, de $\\lambda$ et de la cuve. Valable pour des solutions peu concentrées.", "createdAt": 1793546802141, "updatedAt": 1793546802141, "ocrDone": true}'::jsonb),
('e24934fe-c62b-52a1-893d-70b9b19d8131', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e24934fe-c62b-52a1-893d-70b9b19d8131", "code": "11ER-012", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Beer-Lambert", "étalonnage", "méthode"], "front": "Méthode : déterminer une concentration inconnue avec des **mesures d''absorbance** ?", "back": "1. Préparer des solutions étalons de concentrations connues.\n2. Mesurer leur absorbance à $\\lambda_{\\max}$.\n3. Tracer la droite d''étalonnage $A = f(C)$.\n4. Mesurer $A$ de l''inconnue et lire $C$ (ou calculer $C = A/k$).", "createdAt": 1793546802142, "updatedAt": 1793546802142, "ocrDone": true}'::jsonb),
('201b70cd-7ab4-5f9d-b044-93310e6fa9b7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "201b70cd-7ab4-5f9d-b044-93310e6fa9b7", "code": "11ER-013", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "absorbance", "expérience"], "front": "Pourquoi régler le spectrophotomètre sur $\\lambda_{\\max}$ ?", "back": "C''est là que l''absorbance est la plus grande : la mesure est plus sensible et plus précise.", "createdAt": 1793546802143, "updatedAt": 1793546802143, "ocrDone": true}'::jsonb),
('5cbdf27d-3212-57d5-940c-d4d31b33ff2d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5cbdf27d-3212-57d5-940c-d4d31b33ff2d", "code": "11ER-014", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydant", "réducteur"], "front": "**Oxydant** et **réducteur** : définitions ?", "back": "**Oxydant** : espèce capable de **capter** un ou plusieurs électrons.\n**Réducteur** : espèce capable de **céder** un ou plusieurs électrons.", "createdAt": 1793546802144, "updatedAt": 1793546802144, "ocrDone": true}'::jsonb),
('957bf4ac-c0ad-5d14-8089-ef01ba1e5232', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "957bf4ac-c0ad-5d14-8089-ef01ba1e5232", "code": "11ER-015", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "couple", "demi-équation"], "front": "Qu''est-ce qu''un **couple oxydant-réducteur** ? Comment s''écrit sa demi-équation ?", "back": "Deux espèces qui se transforment l''une en l''autre par échange d''électrons, notées Ox/Red.\n$\\mathrm{Ox} + n\\,\\mathrm{e^-} = \\mathrm{Red}$\nEx. : $\\mathrm{Cu^{2+}} + 2\\,\\mathrm{e^-} = \\mathrm{Cu}$", "createdAt": 1793546802145, "updatedAt": 1793546802145, "ocrDone": true}'::jsonb),
('0705608c-f2da-530b-a0dd-aa9d10a99b98', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0705608c-f2da-530b-a0dd-aa9d10a99b98", "code": "11ER-016", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydo-réduction"], "front": "Qu''est-ce qu''une **réaction d''oxydo-réduction** ?", "back": "Un **transfert d''électrons** du réducteur d''un couple vers l''oxydant d''un autre couple.", "createdAt": 1793546802146, "updatedAt": 1793546802146, "ocrDone": true}'::jsonb),
('64ec46ec-b441-5423-a5d5-4a99da72f679', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "64ec46ec-b441-5423-a5d5-4a99da72f679", "code": "11ER-017", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "demi-équation", "méthode"], "front": "Méthode : équilibrer une **demi-équation en milieu acide** ?", "back": "1. Équilibrer les éléments autres que O et H.\n2. Équilibrer O avec $\\mathrm{H_2O}$.\n3. Équilibrer H avec $\\mathrm{H^+}$.\n4. Équilibrer les charges avec $\\mathrm{e^-}$.\nEx. : $\\mathrm{MnO_4^-} + 8\\,\\mathrm{H^+} + 5\\,\\mathrm{e^-} = \\mathrm{Mn^{2+}} + 4\\,\\mathrm{H_2O}$", "createdAt": 1793546802147, "updatedAt": 1793546802147, "ocrDone": true}'::jsonb),
('4f2047c8-102c-531f-a1f6-8c8c1e0822b1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4f2047c8-102c-531f-a1f6-8c8c1e0822b1", "code": "11ER-018", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydo-réduction", "méthode"], "front": "Méthode : écrire l''**équation d''une réaction** à partir de deux couples ?", "back": "1. Écrire les deux demi-équations dans le sens où elles se font.\n2. Les multiplier pour que le **nombre d''électrons** soit le même.\n3. Les additionner : les électrons disparaissent.", "createdAt": 1793546802148, "updatedAt": 1793546802148, "ocrDone": true}'::jsonb),
('713fe9e0-a423-578e-aecf-12a86b713823', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "713fe9e0-a423-578e-aecf-12a86b713823", "code": "11ER-019", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement"], "front": "Qu''est-ce que l''**avancement** $x$ d''une réaction ?", "back": "Une grandeur en **mol** qui décrit l''évolution du système : elle vaut 0 à l''état initial et augmente jusqu''à $x_f$ à l''état final.", "createdAt": 1793546802149, "updatedAt": 1793546802149, "ocrDone": true}'::jsonb),
('5409b111-8ee1-5699-b93e-815e66242578', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5409b111-8ee1-5699-b93e-815e66242578", "code": "11ER-020", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "tableau d''avancement", "méthode"], "front": "Construire le **tableau d''avancement** de $a\\,\\mathrm{A} + b\\,\\mathrm{B} \\to c\\,\\mathrm{C}$.", "back": "Les réactifs diminuent, les produits augmentent, selon les nombres stœchiométriques.<table style=\"border-collapse:collapse;margin:8px auto\"><tr><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$a\\,\\mathrm{A}$</td><td style=\"border:1px solid #999;padding:4px 10px\">+</td><td style=\"border:1px solid #999;padding:4px 10px\">$b\\,\\mathrm{B}$</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\to$</td><td style=\"border:1px solid #999;padding:4px 10px\">$c\\,\\mathrm{C}$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">État initial ($x = 0$)</td><td style=\"border:1px solid #999;padding:4px 10px\">$n_A$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$n_B$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">0</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">En cours ($x$)</td><td style=\"border:1px solid #999;padding:4px 10px\">$n_A - ax$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$n_B - bx$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$cx$</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">État final ($x_f$)</td><td style=\"border:1px solid #999;padding:4px 10px\">$n_A - ax_f$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$n_B - bx_f$</td><td style=\"border:1px solid #999;padding:4px 10px\"></td><td style=\"border:1px solid #999;padding:4px 10px\">$cx_f$</td></tr></table>", "createdAt": 1793546802150, "updatedAt": 1793546802150, "ocrDone": true}'::jsonb),
('112333f6-02b8-5db7-a834-25924146763e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "112333f6-02b8-5db7-a834-25924146763e", "code": "11ER-021", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement", "réactif limitant", "méthode"], "front": "Comment déterminer l''**avancement maximal** $x_{\\max}$ et le **réactif limitant** ?", "back": "On résout $n_A - a\\,x_{\\max} = 0$ et $n_B - b\\,x_{\\max} = 0$.\n$x_{\\max}$ est la **plus petite** valeur trouvée ; le réactif correspondant est le **limitant**.", "createdAt": 1793546802151, "updatedAt": 1793546802151, "ocrDone": true}'::jsonb),
('5a00c175-4f65-59b4-b986-f755e7f06112', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5a00c175-4f65-59b4-b986-f755e7f06112", "code": "11ER-022", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement", "transformation"], "front": "Transformation **totale** ou **non totale** : comment les distinguer ?", "back": "**Totale** : $x_f = x_{\\max}$ (le réactif limitant est entièrement consommé).\n**Non totale** : $x_f \\lt x_{\\max}$ (il reste de tous les réactifs).", "createdAt": 1793546802152, "updatedAt": 1793546802152, "ocrDone": true}'::jsonb),
('c1e1554f-0560-5689-899b-178ee75d6b87', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c1e1554f-0560-5689-899b-178ee75d6b87", "code": "11ER-023", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "stœchiométrie"], "front": "Qu''est-ce qu''un **mélange stœchiométrique** ?", "back": "Les réactifs sont introduits dans les proportions de l''équation : $\\dfrac{n_A}{a} = \\dfrac{n_B}{b}$.\nSi la transformation est totale, ils sont tous entièrement consommés.", "createdAt": 1793546802153, "updatedAt": 1793546802153, "ocrDone": true}'::jsonb),
('57c56897-feb5-5e73-9a57-1b0b97300b55', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "57c56897-feb5-5e73-9a57-1b0b97300b55", "code": "11ER-024", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "titrage", "vocabulaire"], "front": "À quoi sert un **titrage** ? Qui sont le titrant et le titré ?", "back": "À déterminer la quantité de matière (ou la concentration) d''une espèce grâce à une réaction totale.\n**Titré** : l''espèce cherchée, dans l''erlenmeyer.\n**Titrant** : le réactif de concentration connue, dans la burette.", "createdAt": 1793546802154, "updatedAt": 1793546802154, "ocrDone": true}'::jsonb),
('c27ad3db-d6af-5e2f-a607-302113a177ba', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c27ad3db-d6af-5e2f-a607-302113a177ba", "code": "11ER-025", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "titrage", "équivalence"], "front": "Définir l''**équivalence** d''un titrage.", "back": "Moment où les réactifs ont été introduits dans les **proportions stœchiométriques** : ils sont tous les deux entièrement consommés.\nC''est là que le **réactif limitant change** : avant, le titrant est limitant ; après, c''est le titré.", "createdAt": 1793546802155, "updatedAt": 1793546802155, "ocrDone": true}'::jsonb),
('75b32283-23ae-55eb-b410-1c7726c3e185', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "75b32283-23ae-55eb-b410-1c7726c3e185", "code": "11ER-026", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "titrage", "équivalence"], "front": "Pour la réaction $a\\,\\mathrm{A} + b\\,\\mathrm{B} \\to \\dots$ ($\\mathrm{A}$ titré, $\\mathrm{B}$ titrant), quelle **relation à l''équivalence** ?", "back": "$\\dfrac{n_{A,\\text{initial}}}{a} = \\dfrac{n_{B,\\text{versé}}}{b}$ soit $\\dfrac{C_A V_A}{a} = \\dfrac{C_B V_E}{b}$\n$V_E$ : volume versé à l''équivalence.", "createdAt": 1793546802156, "updatedAt": 1793546802156, "ocrDone": true}'::jsonb),
('c79a478d-a1af-562f-ae6b-556a9d60e097', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c79a478d-a1af-562f-ae6b-556a9d60e097", "code": "11ER-027", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "titrage", "équivalence", "couleur"], "front": "Comment repère-t-on l''équivalence par **colorimétrie** ?", "back": "Par un changement de couleur dû à une espèce colorée qui disparaît ou qui persiste.\nEx. : avec $\\mathrm{MnO_4^-}$ (violet) dans la burette, il est consommé jusqu''à l''équivalence ; **juste après**, une teinte violette persiste.", "createdAt": 1793546802157, "updatedAt": 1793546802157, "ocrDone": true}'::jsonb),
('4a83bb7f-4341-5d20-b767-817cfc982d95', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4a83bb7f-4341-5d20-b767-817cfc982d95", "code": "11ER-028", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Lewis"], "front": "Que représente un **schéma de Lewis** ?", "back": "Les atomes d''une entité et tous leurs **électrons de valence**, regroupés en doublets **liants** (liaisons) et **non liants**, ainsi que les éventuelles **lacunes** et charges.", "createdAt": 1793546802158, "updatedAt": 1793546802158, "ocrDone": true}'::jsonb),
('9e8687c6-8cb4-5d17-b1bc-0f37d7fa5a12', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9e8687c6-8cb4-5d17-b1bc-0f37d7fa5a12", "code": "11ER-029", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Lewis", "stabilité"], "front": "Règles de stabilité (**duet** et **octet**) ?", "back": "Un atome tend à avoir la structure du gaz noble le plus proche :\nH : 2 électrons autour de lui (**duet**).\nC, N, O, F, Cl… : 8 électrons autour de lui (**octet**).", "createdAt": 1793546802159, "updatedAt": 1793546802159, "ocrDone": true}'::jsonb),
('d7d4757a-456e-5b5c-bbab-8bfe8e3e6f76', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d7d4757a-456e-5b5c-bbab-8bfe8e3e6f76", "code": "11ER-030", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Lewis"], "front": "Nombre de liaisons et de doublets non liants habituels de H, C, N, O, Cl ?", "back": "H : 1 liaison, 0 doublet\nC : 4 liaisons, 0 doublet\nN : 3 liaisons, 1 doublet\nO : 2 liaisons, 2 doublets\nCl : 1 liaison, 3 doublets", "createdAt": 1793546802160, "updatedAt": 1793546802160, "ocrDone": true}'::jsonb),
('5fd4b3da-4e5a-5709-b88c-dacbf75d3e6d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5fd4b3da-4e5a-5709-b88c-dacbf75d3e6d", "code": "11ER-031", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "Lewis", "lacune"], "front": "Qu''est-ce qu''une **lacune électronique** ? Exemple ?", "back": "Il manque un doublet à un atome pour respecter sa règle de stabilité ; on la note par un petit rectangle.\nEx. : $\\mathrm{H^+}$ (aucun électron autour de H).", "createdAt": 1793546802161, "updatedAt": 1793546802161, "ocrDone": true}'::jsonb),
('76ce053e-2e4a-5e12-851f-f414b8c88c37', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "76ce053e-2e4a-5e12-851f-f414b8c88c37", "code": "11ER-032", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "géométrie"], "front": "Comment prévoir la **géométrie** d''une entité ?", "back": "Les doublets (liants et non liants) autour d''un atome se **repoussent** et s''écartent au maximum.\nEx. : $\\mathrm{CH_4}$ tétraédrique, $\\mathrm{NH_3}$ pyramidale, $\\mathrm{H_2O}$ coudée, $\\mathrm{CO_2}$ linéaire.", "createdAt": 1793546802162, "updatedAt": 1793546802162, "ocrDone": true}'::jsonb),
('a378c621-2e0d-5257-8d24-149668e48816', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a378c621-2e0d-5257-8d24-149668e48816", "code": "11ER-033", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "électronégativité"], "front": "Qu''est-ce que l''**électronégativité** ? Comment évolue-t-elle dans le tableau périodique ?", "back": "Capacité d''un atome à **attirer vers lui** les électrons d''une liaison.\nElle **augmente** de gauche à droite sur une ligne et de bas en haut dans une colonne (F est le plus électronégatif).", "createdAt": 1793546802163, "updatedAt": 1793546802163, "ocrDone": true}'::jsonb),
('beb30aee-1dda-59ad-8c39-218a721f255e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "beb30aee-1dda-59ad-8c39-218a721f255e", "code": "11ER-034", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "polarité", "liaison"], "front": "Quand une **liaison covalente** est-elle polarisée ?", "back": "Quand les deux atomes ont des électronégativités assez différentes (écart d''environ 0,4 ou plus).\nLe plus électronégatif porte une charge partielle $\\delta^-$, l''autre $\\delta^+$.", "createdAt": 1793546802164, "updatedAt": 1793546802164, "ocrDone": true}'::jsonb),
('860a7127-6450-5a4e-840d-c86e69952a1b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "860a7127-6450-5a4e-840d-c86e69952a1b", "code": "11ER-035", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "polarité", "méthode"], "front": "Comment savoir si une **molécule** est polaire ?", "back": "Il faut des liaisons polarisées **et** une géométrie où les centres des charges partielles $\\delta^+$ et $\\delta^-$ ne coïncident pas.", "createdAt": 1793546802165, "updatedAt": 1793546802165, "ocrDone": true}'::jsonb),
('a844bf50-3f03-5d0a-8d53-b7e29fb4a598', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a844bf50-3f03-5d0a-8d53-b7e29fb4a598", "code": "11ER-036", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "polarité", "géométrie"], "front": "Pourquoi $\\mathrm{H_2O}$ est-elle polaire et $\\mathrm{CO_2}$ apolaire, alors que leurs liaisons sont polarisées ?", "back": "$\\mathrm{H_2O}$ est **coudée** : les centres des charges partielles sont distincts.\n$\\mathrm{CO_2}$ est **linéaire** et symétrique : ils coïncident sur le carbone.", "createdAt": 1793546802166, "updatedAt": 1793546802166, "ocrDone": true}'::jsonb),
('92c09ed5-ebb4-5879-9ce2-bffdd02df61d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "92c09ed5-ebb4-5879-9ce2-bffdd02df61d", "code": "11ER-037", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "cohésion", "interactions"], "front": "Quelles **interactions** assurent la cohésion d''un solide ?", "back": "**Solide ionique** : interactions électrostatiques entre ions.\n**Solide moléculaire** : interactions entre entités polaires, entre entités apolaires, et éventuellement **ponts hydrogène**.", "createdAt": 1793546802167, "updatedAt": 1793546802167, "ocrDone": true}'::jsonb),
('d3983d93-2b07-5730-98a9-4c0093d56ea6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d3983d93-2b07-5730-98a9-4c0093d56ea6", "code": "11ER-038", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "pont hydrogène", "interactions"], "front": "Qu''est-ce qu''un **pont hydrogène** ?", "back": "Une interaction entre un atome H lié à un atome très électronégatif (O, N, F) et un doublet non liant d''un atome O, N ou F d''une autre entité.\nPlus forte que les autres interactions entre molécules.", "createdAt": 1793546802168, "updatedAt": 1793546802168, "ocrDone": true}'::jsonb),
('80cbf945-fb76-5d69-ab9e-877143b8cf9a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "80cbf945-fb76-5d69-ab9e-877143b8cf9a", "code": "11ER-039", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "dissolution"], "front": "Quelles sont les **3 étapes** de la dissolution d''un solide ionique dans l''eau ?", "back": "1. **Dissociation** : l''eau, polaire, sépare les ions.\n2. **Solvatation** : les ions s''entourent de molécules d''eau.\n3. **Dispersion** : ils se répartissent dans la solution.", "createdAt": 1793546802169, "updatedAt": 1793546802169, "ocrDone": true}'::jsonb),
('70cb16b3-d03e-5a19-bdfc-a190eb30eca1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "70cb16b3-d03e-5a19-bdfc-a190eb30eca1", "code": "11ER-040", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "dissolution", "concentration", "méthode"], "front": "Écrire l''équation de dissolution de $\\mathrm{CaCl_2}$. Concentration des ions pour une concentration apportée $C$ ?", "back": "$\\mathrm{CaCl_2(s)} \\to \\mathrm{Ca^{2+}(aq)} + 2\\,\\mathrm{Cl^-(aq)}$\n$[\\mathrm{Ca^{2+}}] = C$ et $[\\mathrm{Cl^-}] = 2C$", "createdAt": 1793546802170, "updatedAt": 1793546802170, "ocrDone": true}'::jsonb),
('205c3c07-7b84-5d51-b814-d1ba15aad14c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "205c3c07-7b84-5d51-b814-d1ba15aad14c", "code": "11ER-041", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "solubilité"], "front": "Comment prévoir si une espèce est **soluble** dans un solvant ?", "back": "Espèces et solvant doivent établir des interactions semblables :\nespèce polaire ou ionique → solvant polaire (eau) ;\nespèce apolaire → solvant apolaire (cyclohexane).", "createdAt": 1793546802171, "updatedAt": 1793546802171, "ocrDone": true}'::jsonb),
('0f91a35a-70bf-56e0-84a5-890827aae32c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0f91a35a-70bf-56e0-84a5-890827aae32c", "code": "11ER-042", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "miscibilité"], "front": "Que signifie **miscibles** ? Exemples ?", "back": "Deux liquides sont miscibles s''ils forment un mélange homogène (une seule phase).\nEau et éthanol : miscibles. Eau et huile : non miscibles.", "createdAt": 1793546802172, "updatedAt": 1793546802172, "ocrDone": true}'::jsonb),
('c9623a99-4028-5ade-a093-497a07d4c32a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c9623a99-4028-5ade-a093-497a07d4c32a", "code": "11ER-043", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "extraction", "méthode"], "front": "Comment choisir le **solvant d''une extraction liquide-liquide** ?", "back": "1. **Non miscible** avec le solvant de départ (souvent l''eau).\n2. L''espèce à extraire y est **plus soluble** que dans le solvant de départ.\nOn regarde aussi la sécurité et l''impact environnemental.", "createdAt": 1793546802173, "updatedAt": 1793546802173, "ocrDone": true}'::jsonb),
('2a47768d-8b03-56f6-b3ab-0357849d74ee', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2a47768d-8b03-56f6-b3ab-0357849d74ee", "code": "11ER-044", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "extraction", "expérience"], "front": "Ampoule à décanter : comment savoir **où se trouve chaque phase** ?", "back": "La phase la plus **dense** est en bas.\nOn compare les densités (ou masses volumiques) des deux solvants.", "createdAt": 1793546802174, "updatedAt": 1793546802174, "ocrDone": true}'::jsonb),
('4e3e9f8a-3f9a-5bdf-bcec-50985adc3960', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4e3e9f8a-3f9a-5bdf-bcec-50985adc3960", "code": "11ER-045", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "savon", "vocabulaire"], "front": "Définir **hydrophile**, **lipophile**, **amphiphile**.", "back": "**Hydrophile** : qui a de l''affinité avec l''eau.\n**Lipophile** : qui a de l''affinité avec les graisses.\n**Amphiphile** : qui possède les deux parties dans la même entité.", "createdAt": 1793546802175, "updatedAt": 1793546802175, "ocrDone": true}'::jsonb),
('748a982d-b2e8-593e-8387-0962eb1da7f1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "748a982d-b2e8-593e-8387-0962eb1da7f1", "code": "11ER-046", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "savon", "tensioactif"], "front": "Comment un **savon** élimine-t-il une salissure grasse ?", "back": "L''ion carboxylate a une **tête** hydrophile ($\\mathrm{-COO^-}$) et une **longue chaîne** lipophile.\nLes chaînes s''accrochent à la graisse, les têtes restent dans l''eau : la graisse est emprisonnée dans des **micelles** et entraînée.", "createdAt": 1793546802176, "updatedAt": 1793546802176, "ocrDone": true}'::jsonb),
('9930d465-bc28-5f55-9033-a84dad6b846b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9930d465-bc28-5f55-9033-a84dad6b846b", "code": "11ER-047", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "formule"], "front": "**Formule brute** et **formule semi-développée** : quelle différence ?", "back": "**Brute** : nombre d''atomes de chaque élément, $\\mathrm{C_2H_6O}$.\n**Semi-développée** : montre les liaisons, sauf celles avec H, $\\mathrm{CH_3{-}CH_2{-}OH}$.", "createdAt": 1793546802177, "updatedAt": 1793546802177, "ocrDone": true}'::jsonb),
('bd2ff25a-0c9d-5932-9cd3-01cfcec62d94', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "bd2ff25a-0c9d-5932-9cd3-01cfcec62d94", "code": "11ER-048", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "alcane", "squelette"], "front": "Qu''est-ce qu''un **squelette carboné saturé** ?", "back": "Une chaîne d''atomes de carbone reliés uniquement par des **liaisons simples**.\nLes **alcanes** (formule $\\mathrm{C_nH_{2n+2}}$) n''ont que ce squelette, sans groupe caractéristique.", "createdAt": 1793546802178, "updatedAt": 1793546802178, "ocrDone": true}'::jsonb),
('77aa3318-7171-5ae2-a2ae-de93cc1ed886', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "77aa3318-7171-5ae2-a2ae-de93cc1ed886", "code": "11ER-049", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "famille", "groupe caractéristique", "nomenclature"], "front": "Les **4 familles** au programme : groupe caractéristique et terminaison du nom ?", "back": "<table style=\"border-collapse:collapse;margin:8px auto\"><tr><td style=\"border:1px solid #999;padding:4px 10px\">Famille</td><td style=\"border:1px solid #999;padding:4px 10px\">Groupe</td><td style=\"border:1px solid #999;padding:4px 10px\">Nom</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">Alcool</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\mathrm{-OH}$ (hydroxyle)</td><td style=\"border:1px solid #999;padding:4px 10px\">-ol</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">Aldéhyde</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\mathrm{-CHO}$ (carbonyle en bout de chaîne)</td><td style=\"border:1px solid #999;padding:4px 10px\">-al</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">Cétone</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\mathrm{C{=}O}$ (carbonyle dans la chaîne)</td><td style=\"border:1px solid #999;padding:4px 10px\">-one</td></tr><tr><td style=\"border:1px solid #999;padding:4px 10px\">Acide carboxylique</td><td style=\"border:1px solid #999;padding:4px 10px\">$\\mathrm{-COOH}$ (carboxyle)</td><td style=\"border:1px solid #999;padding:4px 10px\">acide …-oïque</td></tr></table>", "createdAt": 1793546802179, "updatedAt": 1793546802179, "ocrDone": true}'::jsonb),
('586af51b-150d-5362-87cf-01db0efb5713', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "586af51b-150d-5362-87cf-01db0efb5713", "code": "11ER-050", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "nomenclature"], "front": "**Préfixes** de la chaîne carbonée de 1 à 6 carbones ?", "back": "1 méth-, 2 éth-, 3 prop-, 4 but-, 5 pent-, 6 hex-", "createdAt": 1793546802180, "updatedAt": 1793546802180, "ocrDone": true}'::jsonb),
('53c2ea5c-16d6-5086-8e3b-664d9366c7df', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "53c2ea5c-16d6-5086-8e3b-664d9366c7df", "code": "11ER-051", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "nomenclature", "méthode"], "front": "Méthode : **nommer** une molécule à un groupe caractéristique. Exemple : $\\mathrm{CH_3{-}CH(OH){-}CH_3}$ ?", "back": "1. Chaîne la plus longue portant le groupe → préfixe.\n2. Numéroter pour que le groupe ait le plus petit numéro.\n3. Ajouter les ramifications éventuelles, puis la terminaison.\nEx. : **propan-2-ol**.", "createdAt": 1793546802181, "updatedAt": 1793546802181, "ocrDone": true}'::jsonb),
('63a676ae-e249-5448-9bc0-a16f55779915', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "63a676ae-e249-5448-9bc0-a16f55779915", "code": "11ER-052", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "spectroscopie IR"], "front": "Que montre un **spectre infrarouge** ? Comment l''exploiter ?", "back": "Les bandes d''absorption dues aux **liaisons** de la molécule, en fonction du nombre d''onde (en $\\mathrm{cm^{-1}}$).\nOn compare les bandes à une table de valeurs de référence pour identifier les groupes présents.", "createdAt": 1793546802182, "updatedAt": 1793546802182, "ocrDone": true}'::jsonb),
('ab7f9001-6a47-5a88-b0da-8bdc3f31271b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ab7f9001-6a47-5a88-b0da-8bdc3f31271b", "code": "11ER-053", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "spectroscopie IR"], "front": "Spectre IR : bandes caractéristiques de **O–H** et **C=O** ?", "back": "**O–H** alcool : bande **large** vers $3200$–$3400\\ \\mathrm{cm^{-1}}$.\n**O–H** acide : très large, vers $2500$–$3200\\ \\mathrm{cm^{-1}}$.\n**C=O** : bande **fine et intense** vers $1700\\ \\mathrm{cm^{-1}}$.", "createdAt": 1793546802183, "updatedAt": 1793546802183, "ocrDone": true}'::jsonb),
('32ae565c-2b74-5dda-a78c-0306209a3edb', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "32ae565c-2b74-5dda-a78c-0306209a3edb", "code": "11ER-054", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "synthèse"], "front": "Quelles sont les **4 étapes** d''une synthèse ?", "back": "1. **Transformation** des réactifs.\n2. **Isolement** du produit.\n3. **Purification**.\n4. **Analyse** (identification, pureté).", "createdAt": 1793546802184, "updatedAt": 1793546802184, "ocrDone": true}'::jsonb),
('5c200585-2948-51e4-a050-e5f15ae1a034', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5c200585-2948-51e4-a050-e5f15ae1a034", "code": "11ER-055", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "synthèse", "expérience"], "front": "À quoi sert un **montage à reflux** ?", "back": "**Chauffer** pour accélérer la transformation, **sans perte** de matière : les vapeurs se condensent dans le réfrigérant et retombent dans le ballon.", "createdAt": 1793546802185, "updatedAt": 1793546802185, "ocrDone": true}'::jsonb),
('96d68985-d40b-516f-a987-3857b1e589f9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "96d68985-d40b-516f-a987-3857b1e589f9", "code": "11ER-056", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "synthèse", "isolement", "purification"], "front": "Méthodes d''**isolement** et de **purification** selon l''état du produit ?", "back": "**Solide** : filtration (Büchner), lavage, recristallisation.\n**Liquide** : extraction liquide-liquide, lavage, séchage, distillation.\nLe choix se justifie par les solubilités et les températures de changement d''état.", "createdAt": 1793546802186, "updatedAt": 1793546802186, "ocrDone": true}'::jsonb),
('1dc34a46-9019-558f-b60a-8ed17b28e00c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1dc34a46-9019-558f-b60a-8ed17b28e00c", "code": "11ER-057", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "synthèse", "analyse"], "front": "Comment **analyser** le produit d''une synthèse ?", "back": "Chromatographie sur couche mince (comparaison à un témoin, une seule tache si pur), température de fusion ou d''ébullition, spectre infrarouge.", "createdAt": 1793546802187, "updatedAt": 1793546802187, "ocrDone": true}'::jsonb),
('8efe45c2-039b-5447-9c1c-cd7564754887', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8efe45c2-039b-5447-9c1c-cd7564754887", "code": "11ER-058", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "rendement", "méthode"], "front": "**Rendement** d''une synthèse : formule et méthode ?", "back": "$\\eta = \\dfrac{n_{\\text{obtenue}}}{n_{\\max}}$ (sans unité, entre 0 et 1)\n$n_{\\max}$ : quantité de produit formée si la réaction était totale, calculée à partir du **réactif limitant**.", "createdAt": 1793546802188, "updatedAt": 1793546802188, "ocrDone": true}'::jsonb),
('29ba8910-2917-5301-8f7f-e33555c18ff2', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "29ba8910-2917-5301-8f7f-e33555c18ff2", "code": "11ER-059", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "combustion"], "front": "Qu''est-ce qu''une **combustion** ? Quels produits si elle est complète ?", "back": "Une réaction d''**oxydo-réduction** entre un combustible et le dioxygène (comburant), qui libère de l''énergie.\nCombustion complète d''un alcane ou d''un alcool : $\\mathrm{CO_2}$ et $\\mathrm{H_2O}$.", "createdAt": 1793546802189, "updatedAt": 1793546802189, "ocrDone": true}'::jsonb),
('5f955cb8-6b35-5f90-bd90-5283687fd160', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5f955cb8-6b35-5f90-bd90-5283687fd160", "code": "11ER-060", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "combustion", "équation"], "front": "Écrire la combustion complète du propane $\\mathrm{C_3H_8}$ et de l''éthanol $\\mathrm{C_2H_6O}$.", "back": "$\\mathrm{C_3H_8 + 5\\,O_2 \\to 3\\,CO_2 + 4\\,H_2O}$\n$\\mathrm{C_2H_6O + 3\\,O_2 \\to 2\\,CO_2 + 3\\,H_2O}$", "createdAt": 1793546802190, "updatedAt": 1793546802190, "ocrDone": true}'::jsonb),
('f5848327-ff5d-5c2b-b068-f13c496a70c7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f5848327-ff5d-5c2b-b068-f13c496a70c7", "code": "11ER-061", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "énergie de liaison", "méthode"], "front": "Comment estimer l''**énergie molaire de réaction** avec les **énergies de liaison** (phase gazeuse) ?", "back": "$E_m = \\sum E_{\\text{liaisons rompues}} - \\sum E_{\\text{liaisons formées}}$\nRompre une liaison **consomme** de l''énergie, en former une en **libère**.\n$E_m \\lt 0$ : réaction **exothermique**.", "createdAt": 1793546802191, "updatedAt": 1793546802191, "ocrDone": true}'::jsonb),
('63394fd9-fffd-5c19-bec4-755aca4333bf', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "63394fd9-fffd-5c19-bec4-755aca4333bf", "code": "11ER-062", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "pouvoir calorifique"], "front": "Qu''est-ce que le **pouvoir calorifique** massique ?", "back": "L''énergie libérée par la combustion d''**1 kg** de combustible, $PC$ en $\\mathrm{J \\cdot kg^{-1}}$ (ou $\\mathrm{kJ \\cdot g^{-1}}$).\n$E_{\\text{libérée}} = m \\times PC$", "createdAt": 1793546802192, "updatedAt": 1793546802192, "ocrDone": true}'::jsonb),
('0f7d3f4d-9950-5bd4-a821-ab8d2784980d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0f7d3f4d-9950-5bd4-a821-ab8d2784980d", "code": "11ER-063", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "combustion", "enjeux"], "front": "Combustibles usuels, risques et pistes d''avenir ?", "back": "**Exemples** : gaz naturel, butane, essence, gazole, fioul, bois, éthanol.\n**Risques** : incendie, explosion, intoxication au monoxyde de carbone, émission de $\\mathrm{CO_2}$.\n**Pistes** : carburants agro-sourcés, méthanisation, amélioration des rendements.", "createdAt": 1793546802193, "updatedAt": 1793546802193, "ocrDone": true}'::jsonb),
('9c76c321-1817-5781-8a6b-763851aedbdf', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9c76c321-1817-5781-8a6b-763851aedbdf", "code": "12ER-018", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "charge"], "front": "**Charge électrique** : unité, valeur de la charge élémentaire ?", "back": "En coulomb (C). Charge élémentaire : $e = 1{,}6 \\times 10^{-19}\\ \\mathrm{C}$.\nÉlectron : $-e$ ; proton : $+e$.", "createdAt": 1793546802194, "updatedAt": 1793546802194, "ocrDone": true}'::jsonb),
('e685d309-a68f-5c03-b270-9c8c59fedb83', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e685d309-a68f-5c03-b270-9c8c59fedb83", "code": "12ER-019", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "électrostatique", "influence"], "front": "Qu''est-ce que l''**influence électrostatique** ?", "back": "Un objet chargé approché d''un objet neutre y déplace les charges : les charges de signe opposé se rapprochent et il y a **attraction**, sans contact.\nEx. : une règle frottée attire des morceaux de papier.", "createdAt": 1793546802195, "updatedAt": 1793546802195, "ocrDone": true}'::jsonb),
('f2330342-cfd4-53f8-a337-59b22a5afe14', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f2330342-cfd4-53f8-a337-59b22a5afe14", "code": "12ER-020", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "loi de Coulomb"], "front": "Énoncer la **loi de Coulomb**.", "back": "$F = k\\,\\dfrac{|q_A\\,q_B|}{d^2}$\n$k = 9{,}0 \\times 10^{9}\\ \\mathrm{N \\cdot m^2 \\cdot C^{-2}}$, $q$ en C, $d$ en m.\nCharges de même signe : répulsion. De signes opposés : attraction.", "createdAt": 1793546802196, "updatedAt": 1793546802196, "ocrDone": true}'::jsonb),
('425dfa83-55f7-599e-8db7-9580bc7491a0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "425dfa83-55f7-599e-8db7-9580bc7491a0", "code": "12ER-021", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "loi de Coulomb", "vecteur"], "front": "Expression **vectorielle** de la force électrostatique exercée par A sur B ?", "back": "$\\vec{F}_{A/B} = k\\,\\dfrac{q_A\\,q_B}{d^2}\\,\\vec{u}_{AB}$\n$\\vec{u}_{AB}$ : vecteur unitaire de A vers B.\nSi $q_A q_B \\gt 0$, la force est dans le sens de $\\vec{u}_{AB}$ (répulsion).", "createdAt": 1793546802197, "updatedAt": 1793546802197, "ocrDone": true}'::jsonb),
('0eae8902-a98f-5cf8-a81f-c65a3c1f0c7a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0eae8902-a98f-5cf8-a81f-c65a3c1f0c7a", "code": "12ER-022", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "gravitation", "vecteur"], "front": "Expression **vectorielle** de la force de gravitation exercée par A sur B ?", "back": "$\\vec{F}_{A/B} = -G\\,\\dfrac{m_A\\,m_B}{d^2}\\,\\vec{u}_{AB}$\n$G = 6{,}67 \\times 10^{-11}\\ \\mathrm{N \\cdot m^2 \\cdot kg^{-2}}$\nLe signe − traduit une force toujours **attractive**.", "createdAt": 1793546802198, "updatedAt": 1793546802198, "ocrDone": true}'::jsonb),
('95f3da57-3883-58ea-b2c5-259c833b4fb9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "95f3da57-3883-58ea-b2c5-259c833b4fb9", "code": "12ER-023", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "loi de Coulomb", "gravitation"], "front": "**Analogies** et **différence** entre interactions gravitationnelle et électrostatique ?", "back": "**Analogies** : même forme en $\\dfrac{1}{d^2}$, proportionnelles au produit de deux grandeurs (masses ou charges), portées par la droite AB.\n**Différence** : la gravitation est toujours attractive ; l''interaction électrostatique peut être attractive ou répulsive.", "createdAt": 1793546802199, "updatedAt": 1793546802199, "ocrDone": true}'::jsonb),
('7f8952ae-98e7-5e5a-8454-1acbbb30a734', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7f8952ae-98e7-5e5a-8454-1acbbb30a734", "code": "12ER-024", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "champ"], "front": "Relation entre **force** et **champ** dans les deux cas ?", "back": "**Gravitation** : $\\vec{F} = m\\,\\vec{\\mathcal{G}}$ ($\\mathcal{G}$ en $\\mathrm{N \\cdot kg^{-1}}$)\n**Électrostatique** : $\\vec{F} = q\\,\\vec{E}$ ($E$ en $\\mathrm{N \\cdot C^{-1}}$ ou $\\mathrm{V \\cdot m^{-1}}$)", "createdAt": 1793546802200, "updatedAt": 1793546802200, "ocrDone": true}'::jsonb),
('7a8f6bae-867c-52ce-a173-f2dd31325280', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7a8f6bae-867c-52ce-a173-f2dd31325280", "code": "12ER-025", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "champ"], "front": "Expression du champ de gravitation créé par une masse $M$, et du champ électrostatique créé par une charge $Q$, à la distance $d$ ?", "back": "$\\mathcal{G} = G\\,\\dfrac{M}{d^2}$, dirigé vers la masse.\n$E = k\\,\\dfrac{|Q|}{d^2}$, s''éloignant de $Q$ si $Q \\gt 0$, dirigé vers $Q$ si $Q \\lt 0$.", "createdAt": 1793546802201, "updatedAt": 1793546802201, "ocrDone": true}'::jsonb),
('4a72897e-d6e5-5882-8d3a-1572b9e36702', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4a72897e-d6e5-5882-8d3a-1572b9e36702", "code": "12ER-026", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "champ", "piège"], "front": "Le sens de $\\vec{F} = q\\vec{E}$ selon le signe de $q$ ?", "back": "$q \\gt 0$ : $\\vec{F}$ et $\\vec{E}$ ont le **même sens**.\n$q \\lt 0$ : ils sont de **sens opposés**.", "createdAt": 1793546802202, "updatedAt": 1793546802202, "ocrDone": true}'::jsonb),
('0871ba7e-4a68-5e76-8167-60a11ff2aeaa', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0871ba7e-4a68-5e76-8167-60a11ff2aeaa", "code": "12ER-027", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "champ", "ligne de champ"], "front": "Qu''est-ce qu''une **ligne de champ** ?", "back": "Une courbe **tangente** au vecteur champ en chacun de ses points, orientée dans le sens du champ.\nChamp électrostatique : elles partent des charges positives et vont vers les charges négatives.", "createdAt": 1793546802203, "updatedAt": 1793546802203, "ocrDone": true}'::jsonb),
('098ebb3f-0a5a-5bdb-9358-a0ca9c297f8e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "098ebb3f-0a5a-5bdb-9358-a0ca9c297f8e", "code": "12ER-028", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "fluide"], "front": "Quelles sont les 3 **grandeurs macroscopiques** qui décrivent un fluide au repos ?", "back": "**Masse volumique** $\\rho$ en $\\mathrm{kg \\cdot m^{-3}}$\n**Pression** $P$ en Pa\n**Température** $T$ en K ($T = \\theta + 273{,}15$)", "createdAt": 1793546802204, "updatedAt": 1793546802204, "ocrDone": true}'::jsonb),
('b78f52dd-c6ea-55db-ae4e-44acefe9cd7c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b78f52dd-c6ea-55db-ae4e-44acefe9cd7c", "code": "12ER-029", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "fluide", "microscopique"], "front": "Interprétation **microscopique** de la pression et de la température ?", "back": "**Pression** : liée aux **chocs** des entités sur les parois.\n**Température** : liée à l''**agitation** des entités ; plus elles s''agitent vite, plus elle est élevée.", "createdAt": 1793546802205, "updatedAt": 1793546802205, "ocrDone": true}'::jsonb),
('df4bb989-de1d-58f2-aec2-3202a7929912', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "df4bb989-de1d-58f2-aec2-3202a7929912", "code": "12ER-030", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "pression", "unité"], "front": "Unités de pression à connaître ?", "back": "Pascal : $1\\ \\mathrm{Pa} = 1\\ \\mathrm{N \\cdot m^{-2}}$\n$1\\ \\mathrm{bar} = 10^5\\ \\mathrm{Pa}$ ; $1\\ \\mathrm{hPa} = 100\\ \\mathrm{Pa}$\nPression atmosphérique normale : environ $1013\\ \\mathrm{hPa}$.", "createdAt": 1793546802206, "updatedAt": 1793546802206, "ocrDone": true}'::jsonb),
('0a24d0ce-e433-5df6-9d1d-b37f273d4bfb', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0a24d0ce-e433-5df6-9d1d-b37f273d4bfb", "code": "12ER-031", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "loi de Mariotte"], "front": "Énoncer la **loi de Mariotte**. Conditions ?", "back": "$P \\times V = \\text{constante}$, soit $P_1 V_1 = P_2 V_2$\nPour une quantité de gaz fixée, à **température constante**, et à pression pas trop élevée.", "createdAt": 1793546802207, "updatedAt": 1793546802207, "ocrDone": true}'::jsonb),
('5b21b512-0389-5456-8f53-1dcff5ce81c5', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5b21b512-0389-5456-8f53-1dcff5ce81c5", "code": "12ER-032", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "force pressante"], "front": "Expression et caractéristiques de la **force pressante** ?", "back": "$F = P \\times S$ (F en N, P en Pa, S en $\\mathrm{m^2}$)\nDirection : **perpendiculaire** à la surface. Sens : du fluide vers la surface.", "createdAt": 1793546802208, "updatedAt": 1793546802208, "ocrDone": true}'::jsonb),
('51aa5851-5fe3-503a-aaa4-60db42012ad1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "51aa5851-5fe3-503a-aaa4-60db42012ad1", "code": "12ER-033", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "statique des fluides"], "front": "Énoncer la **loi fondamentale de la statique des fluides**.", "back": "$P_2 - P_1 = \\rho\\,g\\,(z_1 - z_2)$\nFluide incompressible au repos. L''axe $z$ est orienté vers le **haut**.\nPlus on descend, plus la pression augmente.", "createdAt": 1793546802209, "updatedAt": 1793546802209, "ocrDone": true}'::jsonb),
('3f8ea8a2-30bc-56bf-bf34-3399e442f506', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3f8ea8a2-30bc-56bf-bf34-3399e442f506", "code": "12ER-034", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "statique des fluides", "ordre de grandeur"], "front": "De combien augmente la pression quand on descend de **10 m** dans l''eau ?", "back": "$\\Delta P = \\rho g h = 1000 \\times 9{,}8 \\times 10 \\approx 1 \\times 10^5\\ \\mathrm{Pa}$\nSoit environ **1 bar** de plus tous les 10 m.", "createdAt": 1793546802210, "updatedAt": 1793546802210, "ocrDone": true}'::jsonb),
('217c2ef3-c50d-594e-a156-358358754ace', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "217c2ef3-c50d-594e-a156-358358754ace", "code": "12ER-035", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "variation de vitesse", "méthode"], "front": "Comment construire le **vecteur variation de vitesse** $\\Delta\\vec{v}$ ?", "back": "$\\Delta\\vec{v} = \\vec{v}_{i+1} - \\vec{v}_i$\nOn reporte $\\vec{v}_i$ et $\\vec{v}_{i+1}$ depuis un même point : $\\Delta\\vec{v}$ va de l''extrémité de $\\vec{v}_i$ à celle de $\\vec{v}_{i+1}$.", "createdAt": 1793546802211, "updatedAt": 1793546802211, "ocrDone": true}'::jsonb),
('6b9cc9ec-e554-5868-8604-a407db8bba39', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "6b9cc9ec-e554-5868-8604-a407db8bba39", "code": "12ER-036", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "variation de vitesse", "deuxième loi de Newton"], "front": "Relation entre $\\Delta\\vec{v}$ et la **somme des forces** ?", "back": "$m\\,\\dfrac{\\Delta\\vec{v}}{\\Delta t} \\approx \\sum \\vec{F}$ pour deux instants voisins\n$\\Delta\\vec{v}$ a la même direction et le même sens que $\\sum\\vec{F}$.", "createdAt": 1793546802212, "updatedAt": 1793546802212, "ocrDone": true}'::jsonb),
('832fd199-e59e-5e47-8105-aee3d7c66861', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "832fd199-e59e-5e47-8105-aee3d7c66861", "code": "12ER-037", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "masse", "deuxième loi de Newton"], "front": "Quel est le **rôle de la masse** dans le mouvement ?", "back": "Pour une même force, plus la masse est grande, plus la variation de vitesse est **petite** : la masse traduit l''inertie du système.", "createdAt": 1793546802213, "updatedAt": 1793546802213, "ocrDone": true}'::jsonb),
('4eedd6c1-770a-5a1b-a226-9d6a422640ec', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4eedd6c1-770a-5a1b-a226-9d6a422640ec", "code": "12ER-038", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Mouvement", "tags": ["1re", "Mouvement", "cours", "principe d''inertie"], "front": "Que peut-on dire si $\\sum\\vec{F} = \\vec{0}$ ? Et si $\\sum\\vec{F} \\neq \\vec{0}$ ?", "back": "$\\sum\\vec{F} = \\vec{0}$ : la vitesse ne varie pas, mouvement **rectiligne uniforme** ou repos (principe d''inertie).\n$\\sum\\vec{F} \\neq \\vec{0}$ : le vecteur vitesse **varie** (en valeur et/ou en direction).", "createdAt": 1793546802214, "updatedAt": 1793546802214, "ocrDone": true}'::jsonb),
('eb6e8986-2038-5716-a6fd-cd4cabc68c3f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "eb6e8986-2038-5716-a6fd-cd4cabc68c3f", "code": "13ER-001", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "courant"], "front": "Qui sont les **porteurs de charge** dans un métal ? Dans une solution ?", "back": "**Métal** : les électrons libres.\n**Solution** : les ions.", "createdAt": 1793546802215, "updatedAt": 1793546802215, "ocrDone": true}'::jsonb),
('40834da1-e298-5989-9550-b99c8dac7f83', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "40834da1-e298-5989-9550-b99c8dac7f83", "code": "13ER-002", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "intensité"], "front": "Relation entre **intensité** et **débit de charges** ?", "back": "$I = \\dfrac{Q}{\\Delta t}$\n$I$ en A, $Q$ en C, $\\Delta t$ en s.\nUn ampère : un coulomb par seconde.", "createdAt": 1793546802216, "updatedAt": 1793546802216, "ocrDone": true}'::jsonb),
('8c4ba3ba-f467-5a01-a49c-5183ec2ac979', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8c4ba3ba-f467-5a01-a49c-5183ec2ac979", "code": "13ER-003", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "source réelle"], "front": "Modèle d''une **source réelle de tension** : schéma et relation ?", "back": "Une source idéale de tension $E$ en série avec une résistance interne $r$.\n$U = E - r\\,I$", "createdAt": 1793546802217, "updatedAt": 1793546802217, "ocrDone": true}'::jsonb),
('3c504bd6-c065-5fdf-b7f7-324496e66316', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "3c504bd6-c065-5fdf-b7f7-324496e66316", "code": "13ER-004", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "source réelle", "caractéristique"], "front": "Comment lire $E$ et $r$ sur la **caractéristique** $U = f(I)$ d''une pile ?", "back": "C''est une droite décroissante.\n$E$ : ordonnée à l''origine (tension à vide).\n$r$ : opposé du coefficient directeur.", "createdAt": 1793546802218, "updatedAt": 1793546802218, "ocrDone": true}'::jsonb),
('ed125cd9-c9f5-5204-ad6c-09f9664ebaee', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ed125cd9-c9f5-5204-ad6c-09f9664ebaee", "code": "13ER-005", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "source réelle"], "front": "**Conséquences pratiques** de la résistance interne d''une source ?", "back": "La tension aux bornes **diminue** quand le courant augmente.\nUne partie de l''énergie est perdue en chaleur (la pile chauffe).\nLe courant est limité, au plus $I_{cc} = \\dfrac{E}{r}$ en court-circuit.", "createdAt": 1793546802219, "updatedAt": 1793546802219, "ocrDone": true}'::jsonb),
('a6761620-a452-5298-a791-af6afdb2c712', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a6761620-a452-5298-a791-af6afdb2c712", "code": "13ER-006", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "puissance", "énergie"], "front": "Relations entre **puissance**, tension, intensité et **énergie** ?", "back": "$P = U \\times I$ (W)\n$E = P \\times \\Delta t$ (J, avec $\\Delta t$ en s)\n$1\\ \\mathrm{kWh} = 3{,}6 \\times 10^6\\ \\mathrm{J}$", "createdAt": 1793546802220, "updatedAt": 1793546802220, "ocrDone": true}'::jsonb),
('33808509-b009-57ae-b790-c748d14b8230', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "33808509-b009-57ae-b790-c748d14b8230", "code": "13ER-007", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "effet Joule"], "front": "Qu''est-ce que l''**effet Joule** ? Expression pour un dipôle ohmique ?", "back": "Conversion d''énergie électrique en énergie thermique dans un conducteur.\n$P_J = U I = R\\,I^2$", "createdAt": 1793546802221, "updatedAt": 1793546802221, "ocrDone": true}'::jsonb),
('976a1f29-c476-58cb-b779-66fde3b1e83c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "976a1f29-c476-58cb-b779-66fde3b1e83c", "code": "13ER-008", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "bilan de puissance"], "front": "**Bilan de puissance** d''une source réelle qui alimente un circuit ?", "back": "En multipliant $U = E - rI$ par $I$ :\n$EI = UI + rI^2$\nPuissance produite = puissance fournie au circuit + pertes par effet Joule.", "createdAt": 1793546802222, "updatedAt": 1793546802222, "ocrDone": true}'::jsonb),
('f9ef6e65-9e4f-58de-b37c-5ad579a2e940', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f9ef6e65-9e4f-58de-b37c-5ad579a2e940", "code": "13ER-009", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "rendement"], "front": "Définir le **rendement d''un convertisseur**.", "back": "$\\eta = \\dfrac{P_{\\text{utile}}}{P_{\\text{reçue}}} = \\dfrac{E_{\\text{utile}}}{E_{\\text{reçue}}}$\nSans unité, compris entre 0 et 1.", "createdAt": 1793546802223, "updatedAt": 1793546802223, "ocrDone": true}'::jsonb),
('c9f77de4-0d20-5e7c-aaf7-8ab7fb79e209', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c9f77de4-0d20-5e7c-aaf7-8ab7fb79e209", "code": "13ER-010", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "puissance", "ordre de grandeur"], "front": "Quelques **ordres de grandeur** de puissance ?", "back": "Lampe LED : environ 10 W\nOrdinateur portable : environ 50 W\nFour, bouilloire : environ 2 kW\nVoiture : environ 100 kW\nRéacteur nucléaire : environ 1 GW", "createdAt": 1793546802224, "updatedAt": 1793546802224, "ocrDone": true}'::jsonb),
('accb1c5d-823e-5425-adf6-4ac4ef34e45e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "accb1c5d-823e-5425-adf6-4ac4ef34e45e", "code": "13ER-011", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "énergie cinétique"], "front": "Expression de l''**énergie cinétique** ?", "back": "$E_c = \\dfrac{1}{2}\\,m\\,v^2$\n$E_c$ en J, $m$ en kg, $v$ en $\\mathrm{m \\cdot s^{-1}}$.", "createdAt": 1793546802225, "updatedAt": 1793546802225, "ocrDone": true}'::jsonb),
('5098b42e-c244-57d2-8337-df84d9cf78c8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5098b42e-c244-57d2-8337-df84d9cf78c8", "code": "13ER-012", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "travail", "produit scalaire"], "front": "**Travail** d''une force constante sur un déplacement de A à B ?", "back": "$W_{AB}(\\vec{F}) = \\vec{F} \\cdot \\overrightarrow{AB} = F \\times AB \\times \\cos\\alpha$\n$\\alpha$ : angle entre $\\vec{F}$ et $\\overrightarrow{AB}$. En joules.", "createdAt": 1793546802226, "updatedAt": 1793546802226, "ocrDone": true}'::jsonb),
('1afafc5f-2ece-51d2-992f-b3aa60b0ae9b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1afafc5f-2ece-51d2-992f-b3aa60b0ae9b", "code": "13ER-013", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "travail"], "front": "Travail **moteur**, **résistant** ou **nul** : comment les reconnaître ?", "back": "$W \\gt 0$ (moteur) : $\\alpha \\lt 90°$\n$W \\lt 0$ (résistant) : $\\alpha \\gt 90°$\n$W = 0$ : force perpendiculaire au déplacement ($\\alpha = 90°$)", "createdAt": 1793546802227, "updatedAt": 1793546802227, "ocrDone": true}'::jsonb),
('d0e9b7ea-af2d-5982-adc1-479e134f3259', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d0e9b7ea-af2d-5982-adc1-479e134f3259", "code": "13ER-014", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "théorème de l''énergie cinétique"], "front": "Énoncer le **théorème de l''énergie cinétique**.", "back": "$\\Delta E_c = E_c(B) - E_c(A) = \\sum W_{AB}(\\vec{F})$\nLa variation d''énergie cinétique est égale à la somme des travaux de **toutes** les forces.", "createdAt": 1793546802228, "updatedAt": 1793546802228, "ocrDone": true}'::jsonb),
('f3d332bc-45a6-5def-aabb-4a1fa8f228a9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f3d332bc-45a6-5def-aabb-4a1fa8f228a9", "code": "13ER-015", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "travail", "frottement"], "front": "Travail d''une **force de frottement** constante, sur une trajectoire rectiligne de longueur $AB$ ?", "back": "$W_{AB}(\\vec{f}) = -f \\times AB$\nToujours négatif : la force s''oppose au mouvement.", "createdAt": 1793546802229, "updatedAt": 1793546802229, "ocrDone": true}'::jsonb),
('cf1fd033-8872-5d70-a17e-efffbe3b5707', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "cf1fd033-8872-5d70-a17e-efffbe3b5707", "code": "13ER-016", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "force conservative"], "front": "Qu''est-ce qu''une **force conservative** ? Exemples ?", "back": "Son travail **ne dépend pas du chemin suivi**, seulement des points de départ et d''arrivée.\nConservative : le poids.\nNon conservative : les frottements.", "createdAt": 1793546802230, "updatedAt": 1793546802230, "ocrDone": true}'::jsonb),
('5a3a0064-7e50-5a79-a91f-0c3abceef3fa', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5a3a0064-7e50-5a79-a91f-0c3abceef3fa", "code": "13ER-017", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "travail", "poids"], "front": "**Travail du poids** de A à B ?", "back": "$W_{AB}(\\vec{P}) = m\\,g\\,(z_A - z_B)$\nAxe $z$ vers le haut. Moteur quand le système descend, résistant quand il monte.", "createdAt": 1793546802231, "updatedAt": 1793546802231, "ocrDone": true}'::jsonb),
('0383c27f-90e3-576e-8530-9b215dcce527', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0383c27f-90e3-576e-8530-9b215dcce527", "code": "13ER-018", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "énergie potentielle"], "front": "Expression de l''**énergie potentielle de pesanteur** ?", "back": "$E_{pp} = m\\,g\\,z$ (à une constante près : on choisit l''origine)\n$z$ : altitude, axe vers le haut. Lien avec le travail : $W_{AB}(\\vec{P}) = -\\Delta E_{pp}$", "createdAt": 1793546802232, "updatedAt": 1793546802232, "ocrDone": true}'::jsonb),
('a69118ae-3c3c-536f-8984-1900f9b7415c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a69118ae-3c3c-536f-8984-1900f9b7415c", "code": "13ER-019", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "énergie mécanique"], "front": "Définir l''**énergie mécanique**. Quand se conserve-t-elle ?", "back": "$E_m = E_c + E_p$\nElle se **conserve** si seules des forces conservatives travaillent (chute libre sans frottement, pendule sans frottement).", "createdAt": 1793546802233, "updatedAt": 1793546802233, "ocrDone": true}'::jsonb),
('7b4b594f-c7f0-5658-ade9-33f6626d9dfc', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7b4b594f-c7f0-5658-ade9-33f6626d9dfc", "code": "13ER-020", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "énergie mécanique", "frottement"], "front": "Que devient l''énergie mécanique en présence de **forces non conservatives** ?", "back": "$\\Delta E_m = \\sum W(\\vec{F}_{\\text{non conservatives}})$\nAvec des frottements, elle **diminue** : de l''énergie est dissipée sous forme de chaleur.", "createdAt": 1793546802234, "updatedAt": 1793546802234, "ocrDone": true}'::jsonb),
('da65dbd5-5356-57d8-ae65-5902041b4eda', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "da65dbd5-5356-57d8-ae65-5902041b4eda", "code": "13ER-021", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Énergie", "tags": ["1re", "Énergie", "cours", "énergie mécanique", "méthode"], "front": "Vitesse d''un objet lâché sans vitesse initiale, après une **chute libre** de hauteur $h$ ?", "back": "Conservation de $E_m$ : $mgh = \\dfrac{1}{2}mv^2$\nD''où $v = \\sqrt{2gh}$ (indépendante de la masse).", "createdAt": 1793546802235, "updatedAt": 1793546802235, "ocrDone": true}'::jsonb),
('47ed38e2-eef0-555f-bd19-eb1b4b232039', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "47ed38e2-eef0-555f-bd19-eb1b4b232039", "code": "14ER-001", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "onde"], "front": "Qu''est-ce qu''une **onde mécanique progressive** ?", "back": "La propagation d''une **perturbation** dans un milieu matériel, avec transport d''**énergie**, **sans transport de matière**.\nEx. : son, houle, ondes sismiques.", "createdAt": 1793546802236, "updatedAt": 1793546802236, "ocrDone": true}'::jsonb),
('1860950a-62e3-5e2b-9c0a-4d7b9de9392c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1860950a-62e3-5e2b-9c0a-4d7b9de9392c", "code": "14ER-002", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "onde"], "front": "Onde **transversale** ou **longitudinale** : quelle différence ?", "back": "**Transversale** : perturbation perpendiculaire à la propagation (corde, surface de l''eau).\n**Longitudinale** : perturbation parallèle à la propagation (son, ressort comprimé).", "createdAt": 1793546802237, "updatedAt": 1793546802237, "ocrDone": true}'::jsonb),
('b19885f4-57c2-51e8-a22b-0b19f15f61d0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b19885f4-57c2-51e8-a22b-0b19f15f61d0", "code": "14ER-003", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "célérité"], "front": "Qu''est-ce que la **célérité** d''une onde ? De quoi dépend-elle ?", "back": "Sa vitesse de propagation : $v = \\dfrac{d}{\\Delta t}$\nElle dépend du **milieu**. Son : environ $340\\ \\mathrm{m \\cdot s^{-1}}$ dans l''air, $1500\\ \\mathrm{m \\cdot s^{-1}}$ dans l''eau.", "createdAt": 1793546802238, "updatedAt": 1793546802238, "ocrDone": true}'::jsonb),
('56641669-df68-5997-a2cc-9775da431a59', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "56641669-df68-5997-a2cc-9775da431a59", "code": "14ER-004", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "retard", "célérité"], "front": "Qu''est-ce que le **retard** ? Comment le calculer ?", "back": "Durée $\\tau$ entre le passage de la perturbation en deux points distants de $d$ : $\\tau = \\dfrac{d}{v}$\nIl permet de localiser une source (séisme, sonar, échographie).", "createdAt": 1793546802239, "updatedAt": 1793546802239, "ocrDone": true}'::jsonb),
('b7187852-ea31-5c30-a46e-431d3a2c7d6e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b7187852-ea31-5c30-a46e-431d3a2c7d6e", "code": "14ER-005", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "période", "longueur d''onde"], "front": "Double périodicité : qu''est-ce que la **période** $T$ et la **longueur d''onde** $\\lambda$ ?", "back": "**$T$** : périodicité **temporelle**, durée d''un motif (en s).\n**$\\lambda$** : périodicité **spatiale**, distance entre deux points dans le même état vibratoire (en m).", "createdAt": 1793546802240, "updatedAt": 1793546802240, "ocrDone": true}'::jsonb),
('a7e200c6-13de-55c5-a7d0-b83422d6f4d0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a7e200c6-13de-55c5-a7d0-b83422d6f4d0", "code": "14ER-006", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "longueur d''onde", "célérité"], "front": "Relation entre $v$, $\\lambda$, $T$ et $f$ ? Justification ?", "back": "$v = \\dfrac{\\lambda}{T} = \\lambda \\times f$ avec $f = \\dfrac{1}{T}$\nPendant une période $T$, l''onde parcourt exactement une longueur d''onde $\\lambda$.", "createdAt": 1793546802241, "updatedAt": 1793546802241, "ocrDone": true}'::jsonb),
('f75fa531-91f7-5cdc-aba2-7d040d2b3c23', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f75fa531-91f7-5cdc-aba2-7d040d2b3c23", "code": "14ER-007", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "période", "longueur d''onde", "méthode"], "front": "Sur quel graphique lit-on $T$ ? Et $\\lambda$ ?", "back": "**$T$** sur un graphique en fonction du **temps** (ce que fait un point du milieu).\n**$\\lambda$** sur un graphique en fonction de la **position** (photo du milieu à un instant).", "createdAt": 1793546802242, "updatedAt": 1793546802242, "ocrDone": true}'::jsonb),
('8592b345-309d-572e-aeaf-a2116e728d99', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8592b345-309d-572e-aeaf-a2116e728d99", "code": "14ER-008", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "longueur d''onde", "fréquence"], "front": "Qu''est-ce qui détermine $f$ et $\\lambda$ quand une onde change de milieu ?", "back": "La **fréquence** dépend de la **source** : elle ne change pas.\nLa **célérité** dépend du milieu, donc $\\lambda = v/f$ dépend de la source **et** du milieu.", "createdAt": 1793546802243, "updatedAt": 1793546802243, "ocrDone": true}'::jsonb),
('1b61c1bd-cf62-5352-9149-4254d6a95854', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1b61c1bd-cf62-5352-9149-4254d6a95854", "code": "14ER-009", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "lentille", "tracé"], "front": "Quels sont les **3 rayons** particuliers d''une lentille convergente ?", "back": "1. Passant par le centre O : **non dévié**.<br>2. Parallèle à l''axe optique : ressort en passant par **F''**.<br>3. Passant par **F** : ressort parallèle à l''axe optique.<svg viewBox=\"0 0 260 150\" width=\"260\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"10\" y1=\"75\" x2=\"250\" y2=\"75\" stroke=\"#555\" stroke-width=\"1\"/><line x1=\"110\" y1=\"20\" x2=\"110\" y2=\"130\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><line x1=\"50\" y1=\"75\" x2=\"50\" y2=\"45\" stroke=\"#222\" stroke-width=\"2\"/><line x1=\"230\" y1=\"75\" x2=\"230\" y2=\"135\" stroke=\"#c0392b\" stroke-width=\"2\"/><polyline points=\"50,45 110,45 230,135\" fill=\"none\" stroke=\"#e08a00\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"45\" x2=\"230\" y2=\"135\" stroke=\"#2a9d5c\" stroke-width=\"1.5\"/><circle cx=\"70\" cy=\"75\" r=\"2.5\" fill=\"#222\"/><circle cx=\"150\" cy=\"75\" r=\"2.5\" fill=\"#222\"/><text x=\"66\" y=\"90\" font-size=\"11\">F</text><text x=\"146\" y=\"68\" font-size=\"11\">F''</text><text x=\"102\" y=\"90\" font-size=\"11\">O</text><text x=\"42\" y=\"88\" font-size=\"11\">A</text><text x=\"42\" y=\"42\" font-size=\"11\">B</text><text x=\"234\" y=\"70\" font-size=\"11\" fill=\"#c0392b\">A''</text><text x=\"234\" y=\"140\" font-size=\"11\" fill=\"#c0392b\">B''</text></svg>", "createdAt": 1793546802244, "updatedAt": 1793546802244, "ocrDone": true}'::jsonb),
('5d244e89-0c62-5a3e-bf9d-70edae2f04a7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5d244e89-0c62-5a3e-bf9d-70edae2f04a7", "code": "14ER-010", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "lentille", "conjugaison"], "front": "**Relation de conjugaison** d''une lentille mince ?", "back": "$\\dfrac{1}{\\overline{OA''}} - \\dfrac{1}{\\overline{OA}} = \\dfrac{1}{\\overline{OF''}}$\n$\\overline{OF''} = f''$ : distance focale. Les mesures sont **algébriques**, comptées positivement dans le sens de la lumière : un objet réel a $\\overline{OA} \\lt 0$.", "createdAt": 1793546802245, "updatedAt": 1793546802245, "ocrDone": true}'::jsonb),
('79067860-b90a-5de1-a4bd-32e13bd922e6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "79067860-b90a-5de1-a4bd-32e13bd922e6", "code": "14ER-011", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "lentille", "grandissement"], "front": "Expression du **grandissement** ?", "back": "$\\gamma = \\dfrac{\\overline{A''B''}}{\\overline{AB}} = \\dfrac{\\overline{OA''}}{\\overline{OA}}$", "createdAt": 1793546802246, "updatedAt": 1793546802246, "ocrDone": true}'::jsonb),
('276d33ea-4c07-52fa-9fc1-b3ed98c130a6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "276d33ea-4c07-52fa-9fc1-b3ed98c130a6", "code": "14ER-012", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "lentille", "grandissement"], "front": "Que nous dit le **signe** et la **valeur** de $\\gamma$ sur l''image ?", "back": "$\\gamma \\lt 0$ : image **renversée** ; $\\gamma \\gt 0$ : image **droite**.\n$|\\gamma| \\gt 1$ : image **agrandie** ; $|\\gamma| \\lt 1$ : image **réduite**.", "createdAt": 1793546802247, "updatedAt": 1793546802247, "ocrDone": true}'::jsonb),
('0f2a40d5-9c12-51ab-a11b-c3927382ad3b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0f2a40d5-9c12-51ab-a11b-c3927382ad3b", "code": "14ER-013", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "lentille", "image"], "front": "Image **réelle** ou **virtuelle** : quelle différence et quand ?", "back": "**Réelle** ($\\overline{OA''} \\gt 0$) : recueillie sur un écran ; l''objet est avant F.\n**Virtuelle** ($\\overline{OA''} \\lt 0$) : vue seulement à travers la lentille ; l''objet est entre F et O (effet **loupe**), l''image est droite et agrandie.", "createdAt": 1793546802248, "updatedAt": 1793546802248, "ocrDone": true}'::jsonb),
('7174bb03-fc64-51ce-8b38-8e1140075e14', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7174bb03-fc64-51ce-8b38-8e1140075e14", "code": "14ER-014", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "synthèse additive"], "front": "**Synthèse additive** : quand l''utiliser ? Quels résultats ?", "back": "Pour des **lumières** qui se superposent (écrans, projecteurs). Primaires : rouge, vert, bleu.\nR + V = jaune ; R + B = magenta ; V + B = cyan\nR + V + B = blanc", "createdAt": 1793546802249, "updatedAt": 1793546802249, "ocrDone": true}'::jsonb),
('510ea566-09cc-584c-82db-2c24aec1f022', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "510ea566-09cc-584c-82db-2c24aec1f022", "code": "14ER-015", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "synthèse soustractive"], "front": "**Synthèse soustractive** : quand l''utiliser ? Quels résultats ?", "back": "Pour des **filtres, encres, peintures**, qui absorbent une partie de la lumière. Primaires : cyan, magenta, jaune.\nJ + M = rouge ; J + C = vert ; M + C = bleu\nJ + M + C = noir", "createdAt": 1793546802250, "updatedAt": 1793546802250, "ocrDone": true}'::jsonb),
('8b125ffa-8f19-5f4b-bf28-3a1f97057d56', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8b125ffa-8f19-5f4b-bf28-3a1f97057d56", "code": "14ER-016", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "couleurs complémentaires"], "front": "Quelles sont les **couleurs complémentaires** ?", "back": "Deux couleurs dont la superposition des lumières donne du blanc :\nrouge et cyan ; vert et magenta ; bleu et jaune.", "createdAt": 1793546802251, "updatedAt": 1793546802251, "ocrDone": true}'::jsonb),
('c2cf6065-0e1d-533e-b6f9-039a1c815293', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c2cf6065-0e1d-533e-b6f9-039a1c815293", "code": "14ER-017", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "filtre"], "front": "Qu''est-ce qu''un **filtre coloré** ? Exemple : effet d''un filtre jaune sur une lumière blanche ?", "back": "Il **transmet** sa couleur et **absorbe** sa complémentaire.\nUn filtre jaune absorbe le bleu : il laisse passer rouge et vert, qu''on perçoit jaune.", "createdAt": 1793546802252, "updatedAt": 1793546802252, "ocrDone": true}'::jsonb),
('62a65e90-dd9a-5e91-b9df-70f91dd04d3a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "62a65e90-dd9a-5e91-b9df-70f91dd04d3a", "code": "14ER-018", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "couleur des objets"], "front": "Comment prévoir la **couleur perçue d''un objet** ?", "back": "Elle dépend de la lumière reçue et de ce que l''objet **diffuse** (ce qu''il n''absorbe pas).\nEx. : un objet vert éclairé en rouge absorbe le rouge : il paraît **noir**.", "createdAt": 1793546802253, "updatedAt": 1793546802253, "ocrDone": true}'::jsonb),
('05c47619-a1c4-500c-97d3-0d3b6b55ab2d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "05c47619-a1c4-500c-97d3-0d3b6b55ab2d", "code": "14ER-019", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "vision"], "front": "Qu''est-ce que la **trichromie** de la vision ?", "back": "La rétine possède **trois types de cônes**, sensibles au rouge, au vert et au bleu.\nLe cerveau reconstruit la couleur selon leur stimulation.", "createdAt": 1793546802254, "updatedAt": 1793546802254, "ocrDone": true}'::jsonb),
('e6098867-e977-53e4-b751-01266fccbfd6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e6098867-e977-53e4-b751-01266fccbfd6", "code": "14ER-020", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "onde électromagnétique"], "front": "Relation entre **longueur d''onde**, **célérité** et **fréquence** de la lumière ?", "back": "$\\lambda = \\dfrac{c}{\\nu}$\n$c = 3{,}00 \\times 10^8\\ \\mathrm{m \\cdot s^{-1}}$ dans le vide, $\\lambda$ en m, $\\nu$ en Hz.", "createdAt": 1793546802255, "updatedAt": 1793546802255, "ocrDone": true}'::jsonb),
('9ba6737b-42c7-59b7-bd6e-6741917bfbb2', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9ba6737b-42c7-59b7-bd6e-6741917bfbb2", "code": "14ER-021", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "onde électromagnétique", "domaine spectral"], "front": "Ordre des **domaines** des ondes électromagnétiques, par longueur d''onde croissante ?", "back": "Rayons gamma → rayons X → UV → **visible** (400 à 800 nm) → infrarouge → micro-ondes → ondes radio", "createdAt": 1793546802256, "updatedAt": 1793546802256, "ocrDone": true}'::jsonb),
('681a5e2d-9155-5e57-a6f5-e5700642dca0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "681a5e2d-9155-5e57-a6f5-e5700642dca0", "code": "14ER-022", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "onde électromagnétique", "ordre de grandeur"], "front": "**Ordres de grandeur** de longueurs d''onde ou fréquences pour les applications courantes ?", "back": "Rayons X (imagerie médicale) : $\\lambda \\sim 10^{-10}\\ \\mathrm{m}$\nVisible : $\\lambda \\sim 5 \\times 10^{-7}\\ \\mathrm{m}$\nWifi, micro-ondes : $\\nu \\sim 2{,}4\\ \\mathrm{GHz}$ ($\\lambda \\approx 12\\ \\mathrm{cm}$)", "createdAt": 1793546802257, "updatedAt": 1793546802257, "ocrDone": true}'::jsonb),
('2b22cc3f-0b1b-5b2e-bb1c-775579d20733', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2b22cc3f-0b1b-5b2e-bb1c-775579d20733", "code": "14ER-023", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "photon"], "front": "Qu''est-ce qu''un **photon** ? Quelle est son énergie ?", "back": "Particule de lumière, sans masse.\n$E = h\\,\\nu = \\dfrac{h\\,c}{\\lambda}$\n$h = 6{,}63 \\times 10^{-34}\\ \\mathrm{J \\cdot s}$ (constante de Planck)", "createdAt": 1793546802258, "updatedAt": 1793546802258, "ocrDone": true}'::jsonb),
('ee15a905-1863-5503-b090-0f57d4d20b02', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ee15a905-1863-5503-b090-0f57d4d20b02", "code": "14ER-024", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "photon", "unité"], "front": "Conversion **électronvolt** et joule ?", "back": "$1\\ \\mathrm{eV} = 1{,}60 \\times 10^{-19}\\ \\mathrm{J}$\nDe eV vers J : on multiplie. De J vers eV : on divise.", "createdAt": 1793546802259, "updatedAt": 1793546802259, "ocrDone": true}'::jsonb),
('7a2acb57-3057-5092-ba1b-4703e742b841', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7a2acb57-3057-5092-ba1b-4703e742b841", "code": "14ER-025", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "niveaux d''énergie"], "front": "Que signifie : l''énergie d''un atome est **quantifiée** ?", "back": "Elle ne peut prendre que certaines valeurs, les **niveaux d''énergie**.\nLe plus bas est l''**état fondamental**, les autres sont des états **excités**.", "createdAt": 1793546802260, "updatedAt": 1793546802260, "ocrDone": true}'::jsonb),
('33b6aeea-fb8e-5789-b1fe-362e14b3ada0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "33b6aeea-fb8e-5789-b1fe-362e14b3ada0", "code": "14ER-026", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "niveaux d''énergie", "interaction lumière-matière"], "front": "**Absorption** et **émission** d''un photon : que se passe-t-il ?", "back": "**Absorption** : l''atome passe à un niveau **supérieur** en absorbant un photon d''énergie exactement égale à l''écart.\n**Émission** : il redescend à un niveau **inférieur** en émettant un photon.", "createdAt": 1793546802261, "updatedAt": 1793546802261, "ocrDone": true}'::jsonb),
('aee0bc20-1392-51a0-91d2-9b0cdbdfb653', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "aee0bc20-1392-51a0-91d2-9b0cdbdfb653", "code": "14ER-027", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "niveaux d''énergie", "méthode"], "front": "Lien entre une **transition** et la longueur d''onde du photon ?", "back": "$\\Delta E = |E_{\\text{sup}} - E_{\\text{inf}}| = h\\,\\nu = \\dfrac{h\\,c}{\\lambda}$\nD''où $\\lambda = \\dfrac{h\\,c}{\\Delta E}$ ($\\Delta E$ en **joules**).", "createdAt": 1793546802262, "updatedAt": 1793546802262, "ocrDone": true}'::jsonb),
('6c8fd7ab-48ed-5328-addd-dc4dfefc71e1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "6c8fd7ab-48ed-5328-addd-dc4dfefc71e1", "code": "14ER-028", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "spectre", "niveaux d''énergie"], "front": "Pourquoi le **spectre d''émission** d''un gaz est-il fait de raies ?", "back": "Car seules certaines transitions sont possibles : chaque écart d''énergie correspond à une **seule** longueur d''onde.\nChaque élément a donc un spectre qui lui est propre.", "createdAt": 1793546802263, "updatedAt": 1793546802263, "ocrDone": true}'::jsonb);
